new='''def _header_block_fast(cap, block_start, header_start):
    """Parse a complete header section from progressively larger windows.

    Short/repeated header blocks are by far the common case in a capture
    audit.  Find the header terminator in a bounded materialized window and
    validate/split the fields once, rather than revisiting the rope per line.
    """
    remaining = cap.total - header_start
    if remaining <= 0:
        return _header_block_slow(cap, block_start, header_start)
    window = min(remaining, 256)
    cap_window = min(remaining, 65536)
    while True:
        data = cap.read(header_start, header_start + window, window)
        terminator = None
        if data.startswith(b"\\r\\n"):
            terminator = 2
        else:
            found = data.find(b"\\r\\n\\r\\n")
            if found >= 0:
                terminator = found + 4
        if terminator is not None:
            headers = []
            pos = 0
            while True:
                lf = data.find(b"\\n", pos)
                if lf < 0 or lf + 1 > terminator:
                    raise _ParseFailure("syntax")
                if lf == pos or data[lf - 1] != 0x0D:
                    raise _ParseFailure("syntax")
                content_length = lf - 1 - pos
                if content_length > 8192:
                    raise _ParseFailure("syntax")
                next_global = header_start + lf + 1
                if next_global - block_start > 65536:
                    raise _ParseFailure("syntax")
                content = data[pos:lf - 1]
                if content == b"":
                    return headers, next_global
                if len(headers) + 1 > 128:
                    raise _ParseFailure("syntax")
                headers.append(_field(content))
                pos = lf + 1
        if window == remaining or window >= cap_window:
            break
        window = min(cap_window, window * 2)
    return _header_block_slow(cap, block_start, header_start)
'''
